PROPOSED v2 interface:

```ts
export type MeterKind = 'subscription' | 'metered' | 'local' | 'unknown';
export type Approval = 'never' | 'on-request' | 'on-failure';
export type Sandbox  = 'none' | 'read-only' | 'workspace-write';
export type Effort   = 'low' | 'medium' | 'high' | 'xhigh';

export interface HarnessCapabilities {
  // session (from #307, unchanged - these two are proven)
  warmSessions: boolean;        // can hold a warm base at all
  seedableSessions: boolean;    // the CALLER may name the base id
  forkSessions: boolean;        // NEW: fork-off-base is the per-task wipe;
                                //      a harness that can resume but not fork
                                //      needs an explicit scratch-reset instead
  // usage / money
  cacheUsageSplit: boolean;     // drives fidelityFor()
  reportsCost: boolean;         // NEW: emits its own cost (claude total_cost_usd,
                                //      opencode `cost`) - stop re-deriving it
  meter: MeterKind;             // NEW, not a boolean: #301 forbids summing
                                //      subscription and metered spend
  // control surface
  toolAllowlist: boolean;
  effortControl: boolean;       // NEW: --model-reasoning-effort / -c ...
  sandboxModes: Sandbox[];      // NEW: replaces the free-string permissionMode
  promptTransport: 'stdin' | 'argv';  // NEW: decides shell:true vs shell:false
  // liveness
  streamsUsage: boolean;        // NEW: is mid-run usage available at all?
                                //      (gates the generic budget wrapper)
  cancellable: boolean;         // NEW: honours an AbortSignal per run
  transcripts: boolean;         // NEW: can emit a per-run event log
  quota: boolean;               // NEW: can answer quotaLeft() pre-flight
}

export interface HarnessRunOptions {
  cwd: string;
  model?: string;
  effort?: Effort;
  approval?: Approval;
  sandbox?: Sandbox;
  tools?: string[];
  session?: { seed?: string; resume?: string; fork?: boolean };
  budget?: StudentBudget;
  idleTicks?: number;
  signal?: AbortSignal;              // per-run cancel, replaces killAll-only
  transcriptSink?: (line: string) => void;   // raw events, caller owns the file
  onUsage?: (u: CliUsage) => void;
  onBudgetStop?: (i: { turns: number; tokens: number; limit: keyof StudentBudget }) => void;
  onIdleKill?: (i: { ticks: number; lastText: string }) => void;
  // injection seams, kept: every test in this repo depends on them
  spawnFn?: typeof spawn;
  setIntervalFn?: (fn: () => void, ms: number) => NodeJS.Timeout;
  // deliberately NOT here: claudeBin. Bin resolution is the adapter's job,
  // fed from config.harnesses[id].bin + env.
}

export interface HarnessRunResult extends CliTaskResult {
  transcriptPath?: string;      // NEW
  costUsd?: number | null;      // NEW, only when capabilities.reportsCost
  meter: MeterKind;             // NEW, travels WITH the numbers like fidelity
  raw?: unknown;                // the terminal result event, unmangled
}

export type FailureKind = 'capacity' | 'infra' | 'task' | 'cancelled';
export interface FailureVerdict {
  kind: FailureKind;
  retryAfterMs?: number;        // parsed from the provider's OWN words
  resetAt?: number;             // absolute, capacityReset.ts folded in here
  detail?: string;
}

export interface Harness {
  readonly id: string;
  readonly capabilities: HarnessCapabilities;
  run(prompt: string, opts: HarnessRunOptions): Promise<HarnessRunResult>;
  killAll(): void;
  /** Replaces isCapacityError + the free-floating isInfraFailure, and absorbs
   *  parseCapacityReset so provider-specific wording never leaks upstream. */
  classifyFailure(message: string, now?: number): FailureVerdict;
  /** Optional. Resolves the binary and checks it actually runs; the question
   *  claudeBin.ts deliberately refuses to answer. */
  preflight?(): Promise<{ ok: boolean; bin: string; version?: string; detail?: string }>;
  /** Optional, gated on capabilities.quota. The missing half of #301. */
  quotaLeft?(): Promise<{ meter: MeterKind; usedPct?: number; resetsAt?: number } | null>;
}
```
Everything marked NEW is justified by a concrete gap above; everything unmarked already exists and earned its place.
